export interface WaitEventArgs {
  readonly body: WaitRequest;
  /** The client's version, which the server answers 426 below its floor. */
  readonly grelotVersion: string;
  /** <provider>:<host session id>, the session the request acts as. */
  readonly grelotSession: string;
  /** A delegate's handle, to act as that delegate of the session's identity. */
  readonly grelotAs?: string;
  /** 1 when the agent's own command sent the request. */
  readonly grelotSelf?: string;
}

const waitEventCodes = ["too_many_waits", "ended", "replaced", "too_large", "invalid", "forbidden", "none", "dormant", "delegate_ended", "delegate_gate", "upgrade_required", "timeout", "shutting_down", "internal_error", "rate_limited", "auth_required", "auth_session_expired", "auth_invalid_credentials", "auth_key_invalid", "auth_session_required", "auth_key_required", "auth_unavailable", "auth_method_not_allowed", "auth_not_found"] as const;

export type WaitEventError = (typeof waitEventCodes)[number];

/** A standing wait, held up to 55s, that returns this identity's next nudge */
export const waitEventEndpoint = {
  method: "POST",
  path: "/v1/events/wait",
  codes: waitEventCodes,
  request(args: WaitEventArgs): EndpointSpec {
    const headers: globalThis.Record<string, string> = {};
    headers["Grelot-Version"] = args.grelotVersion;
    headers["Grelot-Session"] = args.grelotSession;
    if (args.grelotAs !== undefined) {
      headers["Grelot-As"] = args.grelotAs;
    }
    if (args.grelotSelf !== undefined) {
      headers["Grelot-Self"] = args.grelotSelf;
    }
    return {
      method: "POST",
      path: "/v1/events/wait",
      body: args.body,
      headers,
      codes: waitEventCodes,
    };
  },
  decode: (v: unknown, status: number): Nudge | undefined => {
    switch (status) {
      case 200:
        return decodeNudge(v);
      case 204:
        return undefined;
      default:
        throw new globalThis.TypeError(`$: expected status 200 or 204, got ${status}`);
    }
  },
} as const;

/** A standing wait, held up to 55s, that returns this identity's next nudge */
export function waitEvent(args: WaitEventArgs, opts?: ClientOpts): globalThis.Promise<ApiResult<Nudge | undefined, WaitEventError>> {
  return clientRequest<Nudge | undefined, WaitEventError>(waitEventEndpoint.request(args), waitEventEndpoint.decode, opts);
}

